package com.bloodlink.ui;
import com.bloodlink.model.BloodGroup; import com.bloodlink.service.InventoryService; import com.bloodlink.util.Theme; import javax.swing.*; import javax.swing.border.EmptyBorder; import java.awt.*; import java.util.Comparator; import java.util.stream.Collectors;
public final class CompatibilityPanel extends JPanel {
 private final InventoryService inventory; private final JComboBox<BloodGroup> patient=new JComboBox<>(BloodGroup.values()); private final JTextArea result=new JTextArea();
 public CompatibilityPanel(InventoryService inventory){this.inventory=inventory;setLayout(new BorderLayout(0,18));setBackground(Theme.BG);setBorder(new EmptyBorder(24,24,24,24));JPanel h=new JPanel();h.setOpaque(false);h.setLayout(new BoxLayout(h,BoxLayout.Y_AXIS));h.add(Theme.title("Compatibility intelligence"));h.add(Box.createVerticalStrut(5));h.add(Theme.subtitle("Find compatible red-cell donor groups and current stock instantly."));add(h,BorderLayout.NORTH);JPanel c=Theme.card();c.setLayout(new BorderLayout(0,18));JPanel form=new JPanel(new FlowLayout(FlowLayout.LEFT,10,0));form.setOpaque(false);form.add(new JLabel("Patient blood group"));form.add(patient);JButton check=Theme.primary("Check compatibility");check.addActionListener(e->update());form.add(check);result.setEditable(false);result.setFont(new Font("Monospaced",Font.PLAIN,16));result.setBackground(Color.WHITE);result.setBorder(new EmptyBorder(14,10,10,10));c.add(form,BorderLayout.NORTH);c.add(new JScrollPane(result),BorderLayout.CENTER);add(c,BorderLayout.CENTER);update();}
 private void update(){BloodGroup g=(BloodGroup)patient.getSelectedItem();String donors=g.compatibleDonors().stream().sorted(Comparator.comparing(BloodGroup::toString)).map(d->String.format("%-4s  %3d units%s",d,inventory.units(d),inventory.lowStock(d)?"   ⚠ low stock":"")).collect(Collectors.joining("\n"));result.setText("Recipient: "+g+"\n\nCompatible donor groups:\n\n"+donors+"\n\nNote: Final transfusion decisions must follow hospital blood-bank protocols and cross-matching.");}
}
